const EMPTY = {};
export const moveFlags = (name) => MOVE_FLAGS[name] || EMPTY;

// The move's own secondaryEffectChance, as an integer percent, 0 when it has
// none. Cmd_seteffectwithchance rolls `Random() % 100 < chance`
// (src/battle_script_commands.c:2906-2932), so the probability is chance/100
// exactly -- Serene Grace doubles it, and no pool set has that ability.
export const secondaryChance = (name) => (MOVE_FLAGS[name] || EMPTY).secondaryChance || 0;

// The move's .target (include/constants/battle.h MOVE_TARGET_*). Phase D F38.
export const moveTarget = (name) => {
  const t = (MOVE_FLAGS[name] || EMPTY).target;
  if (!t) throw new Error(`moveTarget: no MOVE_TARGET for "${name}"`);
  return t;
};
